solution:
type Hours = Int;
type Minutes = Int;

fn hours_to_minutes(h: Hours) -> Minutes {
  h * 60
}

fn main() -> Int {
  let workday: Hours = 8;
  let result = hours_to_minutes(workday);
  return result;
}
